insert into public.content_items (kind,slug,status,draft,sort_order,has_unpublished_changes,published_at)
select kind, slug, 'published', case when kind='app' then (select t from tpl) || spec else spec end, sort_order, false, now() from src
on conflict (kind,slug) do nothing;
insert into public.published_content (item_id,kind,slug,data,sort_order,media_paths,published_at)
select id,kind,slug,draft,sort_order,'{}',now() from public.content_items where status='published'
on conflict do nothing;
revoke execute on function public.has_role(uuid, public.app_role) from authenticated;
drop policy "Admins manage categories" on public.categories;
create policy "Admins insert categories" on public.categories for insert to authenticated with check (public.is_admin());
create policy "Admins update categories" on public.categories for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins delete categories" on public.categories for delete to authenticated using (public.is_admin());